groups=[('คำสั่ง Firebase SDK','sdk-results.json'),('สิทธิ์โครงการและผู้ใช้จริง','access-results.json'),('Spec ปลายทาง / การปัดความยาว','spec-results.json'),('หน้าจอรุ่นพัฒนา','ui-results.json'),('หน้าจอรุ่น build / 3D','built-results.json'),('ส่งออกจากรุ่น build','export-results.json')]
