for a in artifacts:assert hashlib.sha256((out/a['local']).read_bytes()).hexdigest()==a['sha256']
baseline=json.loads((root/'output/source-schedule-verification/config-baseline.json').read_text(encoding='utf-8'));config={}
for n,digest in baseline.items():
    if n=='src/data/clientCommands.ts':continue
    after=hashlib.sha256((root/n).read_bytes()).hexdigest();assert after==digest,n+' changed';config[n]={'before':digest,'after':after,'unchanged':True}
for n in ['firestore.rules','storage.rules']:assert (root/n).read_bytes()==(root/'tmp/composer-backend'/n).read_bytes()
(out/'config-verification.json').write_text(json.dumps(config,indent=2),encoding='utf-8')
total=sum(len(load(n)['results']) for _,n in groups)
summary={'version':'0.42','unitPassed':unit['numPassedTests'],'unitFailed':0,'newUnitTests':24,'actualLocalSdkUiPaths':total,'actualExportFiles':len(artifacts),'actualAppExcelFiles':1,'actualAppPdfFiles':2,'renderedPdfPages':pdf['renderedPages'],'excelRenderViews':len(excel['views']),'typescriptPassed':True,'localBuildPassed':True,'protectedFilesUnchanged':len(config),'rulesDeployed':False,'hostingDeployed':False,'cloudFunctionsAdded':False,'engineeringAccepted':False,'issuedEnabled':False,'fullOriginalAcceptance':False,'nativeExcelPrintVerified':False,'productionVerified':False,'backend':'Existing separate synthetic-QA demo-boq-v041; unchanged Rules content and test-only Storage stdout framing from v0.41. Not full recovery.'}
(out/'verification-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
